152	### Connect to Platform Lifecycle
153	
154	```kotlin
155	// commonMain/kotlin/coroutines/LifecycleAwareFlow.kt
156	fun <T> Flow<T>.collectWhileActive(
157	    lifecycle: Lifecycle,
158	    context: CoroutineContext = PlatformDispatchers.main,
159	    collector: suspend (value: T) -> Unit
160	): Job {
161	    val job = SupervisorJob()
162	    val scope = CoroutineScope(job + context)
163	
164	    lifecycle.subscribe { event ->
165	        when (event) {
166	            Lifecycle.Event.ON_RESUME -> {
167	                // Start collecting
168	                scope.launch {
169	                    collect(collector)
170	                }
171	            }
172	            Lifecycle.Event.ON_PAUSE -> {
173	                // Cancel collection
174	                job.cancelChildren()
175	            }
176	            else -> { /* ignore */ }
177	        }
178	    }
179	
180	    return job
181	}
182	
183	// Simple repeat on view active
184	fun <T> Flow<T>.repeatOnViewActive(
185	    isActive: () -> Boolean,
186	    minInterval: Duration = 1.seconds
187	): Flow<T> = channelFlow {
188	    var lastValue: T? = null
189	    val collectorJob = launch {
190	        collect { value ->
191	            lastValue = value
192	            if (isActive()) {
193	                send(value)
194	            }
195	        }
196	    }
197	
198	    while (isActive()) {
199	        lastValue?.let { send(it) }
200	        delay(minInterval)
201	    }
202	
203	    collectorJob.cancel()
204	}
205	```
